1: import type {
2:   DatasetInput,
3:   EvalCase,
4:   HardAssertion,
5:   RubricItem,
6: } from "@cjhyy/code-shell-capability-optimization-lab";
7: 
8: // Optional defaulted fields stay absent until edited. The form must not silently
9: // normalize a user's JSON, especially when switching between editing modes.
10: type DefaultedCaseKey = "fixtureRefs" | "rubric" | "hardAssertions" | "missingEvidence";
11: export type EditableCase = Omit<EvalCase, DefaultedCaseKey> &
12:   Partial<Pick<EvalCase, DefaultedCaseKey>>;
13: export type EditableDataset = Omit<DatasetInput, "cases"> & { cases: EditableCase[] };
14: export type EditorParseResult =
15:   | { ok: true; dataset: EditableDataset }
16:   | { ok: false; reason: "json" | "shape" | "unknown" | "size"; path: string };
17: 
18: const DATASET_FIELDS = ["schemaVersion", "title", "taskFamily", "cases"];
19: const CASE_FIELDS = [
20:   "id",
21:   "version",
22:   "sourceGroupId",
23:   "provenance",
24:   "caseRole",
25:   "split",
26:   "input",
27:   "fixtureRefs",
28:   "expected",
29:   "rubric",
30:   "hardAssertions",
31:   "readiness",
32:   "missingEvidence",
33:   "evidence",
34: ];
35: const MAX_EDITOR_BYTES = 16 * 1024 * 1024;
36: 
37: class UnsupportedShape extends Error {
38:   constructor(
39:     readonly path: string,
40:     readonly reason: "shape" | "unknown" = "shape",
41:   ) {
42:     super(path);
43:   }
44: }
45: function object(value: unknown, fields: string[], path: string): Record<string, unknown> {
46:   if (!value || typeof value !== "object" || Array.isArray(value)) throw new UnsupportedShape(path);
47:   const record = value as Record<string, unknown>;
48:   for (const field of Object.keys(record))
49:     if (!fields.includes(field)) throw new UnsupportedShape(`${path}.${field}`, "unknown");
50:   return record;
51: }
52: function requireType(condition: boolean, path: string): asserts condition {
53:   if (!condition) throw new UnsupportedShape(path);
54: }
55: function strings(value: unknown, path: string, limit: number): void {
56:   requireType(Array.isArray(value), path);
57:   requireType(value.length <= limit, path);
58:   value.forEach((item, index) => requireType(typeof item === "string", `${path}.${index}`));
59: }
60: function assertion(value: unknown, path: string): void {
61:   const item = object(value, ["id", "kind", "value", "path"], path);
62:   requireType(typeof item.id === "string", `${path}.id`);
63:   if (item.kind === "contains" || item.kind === "not_contains") {
64:     requireType(!Object.hasOwn(item, "path"), `${path}.path`);
65:     requireType(typeof item.value === "string", `${path}.value`);
66:   } else {
67:     requireType(item.kind === "json_field_equals", `${path}.kind`);
68:     strings(item.path, `${path}.path`, 8);
69:     requireType(
70:       item.value === null ||
71:         typeof item.value === "string" ||
72:         typeof item.value === "boolean" ||
73:         (typeof item.value === "number" && Number.isFinite(item.value)),
74:       `${path}.value`,
75:     );
76:   }
77: }
