79: /** Shape checking only: the worker remains authoritative for dataset validity. */
80: export function parseEditableDataset(text: string): EditorParseResult {
81:   if (new TextEncoder().encode(text).byteLength > MAX_EDITOR_BYTES)
82:     return { ok: false, reason: "size", path: "$" };
83:   let raw: unknown;
84:   try {
85:     raw = JSON.parse(text);
86:   } catch {
87:     return { ok: false, reason: "json", path: "$" };
88:   }
89:   try {
90:     const dataset = object(raw, DATASET_FIELDS, "$");
91:     requireType(dataset.schemaVersion === 1, "$.schemaVersion");
92:     requireType(typeof dataset.title === "string", "$.title");
93:     requireType(typeof dataset.taskFamily === "string", "$.taskFamily");
94:     requireType(Array.isArray(dataset.cases), "$.cases");
95:     requireType(dataset.cases.length <= 200, "$.cases");
96:     dataset.cases.forEach((rawCase, index) => {
97:       const path = `$.cases.${index}`;
98:       const item = object(rawCase, CASE_FIELDS, path);
99:       for (const key of ["id", "sourceGroupId", "input"])
100:         requireType(typeof item[key] === "string", `${path}.${key}`);
101:       requireType(
102:         typeof item.version === "number" && Number.isFinite(item.version),
103:         `${path}.version`,
104:       );
105:       requireType(["real", "synthetic"].includes(String(item.provenance)), `${path}.provenance`);
106:       requireType(
107:         ["target_failure", "regression"].includes(String(item.caseRole)),
108:         `${path}.caseRole`,
109:       );
110:       requireType(["dev", "holdout"].includes(String(item.split)), `${path}.split`);
111:       requireType(
112:         ["analysis_only", "runnable"].includes(String(item.readiness)),
113:         `${path}.readiness`,
114:       );
115:       if (Object.hasOwn(item, "expected"))
116:         requireType(typeof item.expected === "string", `${path}.expected`);
117:       if (Object.hasOwn(item, "evidence")) {
118:         const evidence = object(
119:           item.evidence,
120:           ["bundleHash", "runId", "purpose", "blockHashes"],
121:           `${path}.evidence`,
122:         );
123:         requireType(
124:           typeof evidence.bundleHash === "string" &&
125:             typeof evidence.runId === "string" &&
126:             evidence.purpose === "problem_source_only",
127:           `${path}.evidence`,
128:         );
129:         strings(evidence.blockHashes, `${path}.evidence.blockHashes`, 50);
130:       }
131:       for (const key of ["fixtureRefs", "missingEvidence"])
132:         if (Object.hasOwn(item, key)) strings(item[key], `${path}.${key}`, 32);
133:       if (Object.hasOwn(item, "rubric")) {
134:         requireType(Array.isArray(item.rubric), `${path}.rubric`);
135:         requireType(item.rubric.length <= 16, `${path}.rubric`);
136:         item.rubric.forEach((value, rubricIndex) => {
137:           const rubricPath = `${path}.rubric.${rubricIndex}`;
138:           const rubric = object(value, ["id", "text", "requiresHumanGrading"], rubricPath);
139:           requireType(typeof rubric.id === "string", `${rubricPath}.id`);
140:           requireType(typeof rubric.text === "string", `${rubricPath}.text`);
141:           requireType(
142:             typeof rubric.requiresHumanGrading === "boolean",
143:             `${rubricPath}.requiresHumanGrading`,
144:           );
145:         });
146:       }
147:       if (Object.hasOwn(item, "hardAssertions")) {
148:         requireType(Array.isArray(item.hardAssertions), `${path}.hardAssertions`);
149:         requireType(item.hardAssertions.length <= 16, `${path}.hardAssertions`);
150:         item.hardAssertions.forEach((value, assertionIndex) =>
151:           assertion(value, `${path}.hardAssertions.${assertionIndex}`),
152:         );
153:       }
154:     });
155:     return { ok: true, dataset: raw as EditableDataset };
156:   } catch (error) {
157:     if (error instanceof UnsupportedShape)
158:       return { ok: false, reason: error.reason, path: error.path };
159:     throw error;
160:   }
161: }
