167: function unusedId(existing: string[], base: string): string {
168:   const ids = new Set(existing);
169:   const prefix = base.slice(0, 53);
170:   let index = 1;
171:   while (ids.has(`${prefix}-${index}`)) index++;
172:   return `${prefix}-${index}`;
173: }
174: 
175: export function createEditableCase(dataset: EditableDataset): EditableCase {
176:   return {
177:     id: unusedId(
178:       dataset.cases.map((item) => item.id),
179:       "case",
180:     ),
181:     version: 1,
182:     sourceGroupId: unusedId(
183:       dataset.cases.map((item) => item.sourceGroupId),
184:       "source",
185:     ),
186:     provenance: "synthetic",
187:     caseRole: "target_failure",
188:     split: "dev",
189:     input: "",
190:     readiness: "analysis_only",
191:     fixtureRefs: [],
192:     rubric: [],
193:     hardAssertions: [],
194:     missingEvidence: [],
195:   };
196: }
