198: /** Copies remain in the same source group and split to avoid invented independence. */
199: export function duplicateEditableCase(dataset: EditableDataset, index: number): EditableCase {
200:   const source = dataset.cases[index];
201:   if (!source) throw new Error("Unknown case");
202:   const copied = structuredClone(source);
203:   const safeBase = /^[a-z0-9][a-z0-9._-]*$/.test(source.id) ? source.id : "case";
204:   copied.id = unusedId(
205:     dataset.cases.map((item) => item.id),
206:     `${safeBase}-copy`,
207:   );
208:   return copied;
209: }
210: 
211: export function newRubric(item: EditableCase): RubricItem {
212:   return {
213:     id: unusedId(
214:       [...(item.rubric ?? []), ...(item.hardAssertions ?? [])].map((rule) => rule.id),
215:       "quality",
216:     ),
217:     text: "",
218:     requiresHumanGrading: true,
219:   };
220: }
221: export function newAssertion(item: EditableCase): HardAssertion {
222:   return {
223:     id: unusedId(
224:       [...(item.rubric ?? []), ...(item.hardAssertions ?? [])].map((rule) => rule.id),
225:       "assertion",
226:     ),
227:     kind: "contains",
228:     value: "",
229:   };
230: }
231: export function changeAssertionKind(
232:   item: HardAssertion,
233:   kind: HardAssertion["kind"],
234: ): HardAssertion {
235:   if (kind === item.kind) return item;
236:   return kind === "json_field_equals"
237:     ? { id: item.id, kind, path: ["field"], value: item.value }
238:     : { id: item.id, kind, value: item.value === null ? "null" : String(item.value) };
239: }
240: 
241: export function summarizeEditableDataset(dataset: EditableDataset) {
242:   const runnableHoldout = dataset.cases.filter(
243:     (item) => item.split === "holdout" && item.readiness === "runnable",
244:   );
245:   return {
246:     dev: dataset.cases.filter((item) => item.split === "dev").length,
247:     holdout: dataset.cases.filter((item) => item.split === "holdout").length,
248:     sourceGroups: new Set(dataset.cases.map((item) => item.sourceGroupId)).size,
249:     runnableHoldoutGroups: new Set(runnableHoldout.map((item) => item.sourceGroupId)).size,
250:   };
251: }
